/**
 * Morning briefs (v0.7).
 *
 * A brief is generated by a normal Session at the configured local time: the
 * Host gathers "what actually happened yesterday" (the previous work journal +
 * the real user question / final answer of yesterday's DSH sessions + task
 * outcomes), the current queue/ideas/waits, and asks the model for a fixed
 * four-section brief plus a small structured suggestion list
 * (`<<<SUGGESTIONS_JSON>>>`) that the UI can turn into queued tasks with one
 * click.
 *
 * The module mirrors `host/reports.js`: one 30s timer, one background Session
 * per run, a local deterministic fallback (which still counts as success),
 * restart recovery, and a `kick()` used by the settings handler. The fixed four
 * sections are part of the v0.7 contract (`docs/v0.7-contract.md` §3).
 */
import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  renameSync,
  statSync,
  writeFileSync,
} from 'node:fs'
import { join } from 'node:path'
import {
  DEFAULT_BRIEF_TIME,
  HttpError,
  MAX_BRIEF_SUGGESTIONS,
  REPORT_DATE_PATTERN,
  REPORT_TIME_PATTERN,
  normalizeSuggestion,
  normalizeSuggestions,
} from './store.js'
import { collectSessionDigests } from './reports.js'

export const BRIEF_TICK_MS = 30_000
export const BRIEF_POLL_MS = 1_000
export const BRIEF_MAX_WAIT_MS = 10 * 60 * 1000
export const BRIEF_DATE_PATTERN = REPORT_DATE_PATTERN
export const BRIEF_LIST_LIMIT = 200

const FILE_PATTERN = /^\d{4}-\d{2}-\d{2}\.md$/
const MAX_BRIEF_CHARS = 2_600
const MAX_BULLET_CHARS = 160
const MAX_YESTERDAY = 6
const MAX_WAITING = 4
const MAX_RISK = 3
const MAX_REPORT_CONTEXT = 1_500
const MAX_DIGESTS = 6
const RISK_STALE_MS = 2 * 60 * 60 * 1000
const DEFAULT_SCHEDULE = { reportTime: '21:00', retroTime: '22:00' }
const BRIEF_TITLE = '晨间简报'

/** Markers of the structured suggestion block the model appends (v0.7). */
export const BRIEF_SUGGESTION_START = '<<<SUGGESTIONS_JSON>>>'
export const BRIEF_SUGGESTION_END = '<<<END_SUGGESTIONS>>>'

/** The fixed four sections: text and order are part of the v0.7 contract. */
export const BRIEF_SECTIONS = [
  '## 一、昨天发生了什么',
  '## 二、今天建议先做',
  '## 三、等你处理',
  '## 四、提醒',
]

const STATUS_LABELS = {
  idea: '想法',
  pending: '队列中',
  running: '执行中',
  paused: '已暂停',
  blocked: '等你回复',
  done: '已完成',
  failed: '失败',
  cancelled: '已取消',
}

const ENDED_STATUSES = ['done', 'failed', 'cancelled']
const WAITING_STATUSES = ['blocked', 'paused', 'failed']

function pad(value) {
  return String(value).padStart(2, '0')
}

/** Local calendar date, `YYYY-MM-DD`. */
export function localDateString(time = Date.now()) {
  const date = new Date(time)
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`
}

/** Local wall-clock time, `HH:mm`. */
function localTimeString(time = Date.now()) {
  const date = new Date(time)
  return `${pad(date.getHours())}:${pad(date.getMinutes())}`
}

/** `YYYY-MM-DD` that also names a real calendar day. */
function isRealDate(value) {
  const text = String(value || '')
  if (!REPORT_DATE_PATTERN.test(text)) return false
  const [year, month, day] = text.split('-').map(Number)
  const date = new Date(year, month - 1, day)
  return date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day
}

function errorMessage(error) {
  if (!error) return '未知错误'
  if (typeof error === 'string') return error
  if (typeof error.message === 'string' && error.message) return error.message
  try {
    return JSON.stringify(error)
  } catch {
    return String(error)
  }
}

function trimError(message, limit = 500) {
  const text = String(message || '未知错误')
  return text.length > limit ? `${text.slice(0, limit - 1)}…` : text
}

function sleep(ms) {
  return new Promise(resolve => {
    const handle = setTimeout(resolve, ms)
    if (handle && typeof handle.unref === 'function') handle.unref()
  })
}

function compact(text, limit) {
  const clean = String(text || '').replace(/\s+/g, ' ').trim()
  return clean.length > limit ? `${clean.slice(0, limit)}…` : clean
}

function statusLabel(status) {
  return STATUS_LABELS[status] || status
}

/** Human "how long has it been waiting" text used by the brief body. */
function formatElapsed(value) {
  const ms = Number.isFinite(value) ? Math.max(0, value) : 0
  const minutes = Math.floor(ms / 60_000)
  if (minutes < 1) return '不到 1 分钟'
  if (minutes < 60) return `${minutes} 分钟`
  const hours = Math.floor(minutes / 60)
  const rest = minutes % 60
  return rest === 0 ? `${hours} 小时` : `${hours} 小时 ${rest} 分钟`
}

function taskStamp(task) {
  if (!task || typeof task !== 'object') return 0
  for (const key of ['endedAt', 'updatedAt', 'createdAt']) {
    if (Number.isFinite(task[key])) return task[key]
  }
  return 0
}

function taskTitle(task) {
  return task && typeof task.title === 'string' ? task.title : '未命名任务'
}

/**
 * The timer's due rule: enabled, the local clock has passed the configured
 * time, today has no successful brief yet, and no generation is in flight.
 */
export function isBriefDue(settings, now = Date.now()) {
  if (!settings || settings.enabled !== true) return false
  const time = REPORT_TIME_PATTERN.test(String(settings.time || ''))
    ? settings.time
    : DEFAULT_BRIEF_TIME
  if (localTimeString(now) < time) return false
  if (settings.lastDate === localDateString(now)) return false
  if (settings.generatingDate) return false
  return true
}

// ---------------------------------------------------------------------------
// Data collection (pure read from the store-like object).
// ---------------------------------------------------------------------------

function skillCounts(storeLike) {
  const counts = { proposedSkillCount: 0, activeSkillCount: 0 }
  try {
    const meta = storeLike && typeof storeLike.getEvolutionMeta === 'function'
      ? storeLike.getEvolutionMeta()
      : null
    if (meta && typeof meta === 'object') {
      if (Number.isFinite(meta.proposedSkillCount)) counts.proposedSkillCount = meta.proposedSkillCount
      if (Number.isFinite(meta.activeSkillCount)) counts.activeSkillCount = meta.activeSkillCount
      return counts
    }
    const skills = storeLike && storeLike.evolution && Array.isArray(storeLike.evolution.skills)
      ? storeLike.evolution.skills
      : []
    for (const skill of skills) {
      if (!skill) continue
      if (skill.status === 'proposed') counts.proposedSkillCount += 1
      else if (skill.status === 'active') counts.activeSkillCount += 1
    }
  } catch {
    // A broken store-like object must not break the brief.
  }
  return counts
}

/**
 * How many skill candidates are waiting for adoption. The brief builders accept
 * a bare number (the `collectMorningBriefData` shape) and also the meta object
 * for callers that already have `getEvolutionMeta()` at hand.
 */
function proposedCountOf(skills) {
  if (Number.isFinite(skills)) return Math.max(0, Math.floor(skills))
  if (skills && typeof skills === 'object' && Number.isFinite(skills.proposedSkillCount)) {
    return Math.max(0, Math.floor(skills.proposedSkillCount))
  }
  return 0
}

/**
 * Gather everything the brief prompt needs from the board.
 *
 * - `yesterday`: queue tasks that ENDED yesterday (done/failed/cancelled) in
 *   board order. The array carries a non-enumerable `sessionCount` property so
 *   "DSH workspace sessions" can be counted without breaking array equality.
 * - `running`: currently running tasks.
 * - `waiting`: blocked / paused / failed tasks (blocked first, then paused,
 *   then failed; oldest `updatedAt` first inside a group).
 * - `candidates`: pending tasks in the exact claim order.
 * - `ideas`: idea tasks, newest created first.
 * - `skills`: number of skill candidates (`proposedSkillCount`) waiting for
 *   adoption.
 */
export function collectMorningBriefData(storeLike, now = Date.now(), date) {
  const tasks = Array.isArray(storeLike && storeLike.tasks) ? storeLike.tasks.filter(Boolean) : []
  const baseTime = isRealDate(date) ? new Date(`${date}T00:00:00`).getTime() : now
  const base = new Date(baseTime)
  const todayStart = new Date(base.getFullYear(), base.getMonth(), base.getDate()).getTime()
  const yesterdayStart = new Date(base.getFullYear(), base.getMonth(), base.getDate() - 1).getTime()

  const yesterday = []
  let sessionCount = 0
  for (const task of tasks) {
    if (!task) continue
    if (task.source === 'session') {
      const stamp = taskStamp(task)
      if (stamp >= yesterdayStart && stamp < todayStart) sessionCount += 1
      continue
    }
    if (!ENDED_STATUSES.includes(task.status)) continue
    if (!Number.isFinite(task.endedAt)) continue
    if (task.endedAt >= yesterdayStart && task.endedAt < todayStart) yesterday.push(task)
  }
  // Non-enumerable: readable by the builders, invisible to deepEqual/JSON.
  Object.defineProperty(yesterday, 'sessionCount', {
    value: sessionCount,
    enumerable: false,
    configurable: true,
    writable: true,
  })

  const running = tasks.filter(task => task.status === 'running')
  const waiting = tasks
    .filter(task => WAITING_STATUSES.includes(task.status))
    .sort((left, right) => {
      const order = WAITING_STATUSES.indexOf(left.status) - WAITING_STATUSES.indexOf(right.status)
      if (order !== 0) return order
      return taskStamp(left) - taskStamp(right)
    })
  const candidates = tasks.filter(task => task.status === 'pending')
  const ideas = tasks
    .filter(task => task.status === 'idea')
    .sort((left, right) => (right.createdAt || 0) - (left.createdAt || 0))

  return {
    yesterday,
    running,
    waiting,
    candidates,
    ideas,
    skills: skillCounts(storeLike).proposedSkillCount,
  }
}

// ---------------------------------------------------------------------------
// Prompt + fallback.
// ---------------------------------------------------------------------------

function cleanInline(text) {
  return String(text || '').replace(/\r?\n+/g, ' ').replace(/\s+/g, ' ').trim()
}

function clipText(text, limit) {
  const clean = String(text || '').trim()
  return clean.length > limit ? clean.slice(0, limit) : clean
}

/** First sentence-ish chunk so a long answer becomes a concrete one-liner. */
function firstSentence(text, limit = 200) {
  const clean = cleanInline(text)
  if (clean === '') return ''
  const match = /^(.{1,400}?[。！？!?；;])/.exec(clean)
  const value = match ? match[1] : clean
  return value.length > limit ? `${value.slice(0, limit)}…` : value
}

/** The concrete outcome of one task: final answer, failure reason or last word. */
function taskOutcome(task, limit = 600) {
  if (!task || typeof task !== 'object') return ''
  if (task.result && typeof task.result.finalAnswer === 'string' && task.result.finalAnswer.trim()) {
    return clipText(task.result.finalAnswer, limit)
  }
  if (typeof task.error === 'string' && task.error.trim()) return clipText(task.error, limit)
  if (typeof task.lastMessage === 'string' && task.lastMessage.trim()) return clipText(task.lastMessage, limit)
  return ''
}

function taskAskText(task, limit = 300) {
  if (!task || typeof task !== 'object') return ''
  if (typeof task.prompt === 'string' && task.prompt.trim()) return clipText(task.prompt, limit)
  return clipText(task.title, limit)
}

/** Local calendar date one day before `date` (or before now). */
function previousDateString(date) {
  const text = isRealDate(date) ? date : localDateString()
  const [year, month, day] = text.split('-').map(Number)
  return localDateString(new Date(year, month - 1, day - 1).getTime())
}

/**
 * Read yesterday's work journal (the `reports/YYYY-MM-DD.md` file) as the main
 * context for "what happened yesterday". Missing file -> ''.
 */
function readJournalText(storeLike, date) {
  const daily = storeLike && storeLike.settings && storeLike.settings.dailyReport
    ? storeLike.settings.dailyReport
    : {}
  const dir = typeof daily.dir === 'string' ? daily.dir : join(storeLike && storeLike.dir ? storeLike.dir : '', 'reports')
  if (!dir) return ''
  const path = join(dir, `${date}.md`)
  try {
    if (!existsSync(path)) return ''
    return clipText(readFileSync(path, 'utf8'), MAX_REPORT_CONTEXT)
  } catch {
    return ''
  }
}

/** Concrete bullets out of a journal body (markdown headings are skipped). */
function journalHighlights(reportText, limit = 4) {
  const out = []
  for (const raw of String(reportText || '').split('\n')) {
    const line = raw.trim()
    if (!/^[-*+]\s+/.test(line)) continue
    const text = cleanInline(line.replace(/^[-*+]\s+/, '').replace(/[*`_]/g, ''))
    if (!text) continue
    out.push(clipText(text, 180))
    if (out.length >= limit) break
  }
  return out
}

function digestHighlights(sessionDigests, limit = 3) {
  const out = []
  for (const digest of Array.isArray(sessionDigests) ? sessionDigests : []) {
    const answer = firstSentence(digest && digest.answer, 140)
    if (!answer) continue
    const title = cleanInline(digest && digest.title) || 'DSH 会话'
    out.push(`${title}：${answer}`)
    if (out.length >= limit) break
  }
  return out
}

// ---------------------------------------------------------------------------
// Structured suggestions (v0.7): parsed out of the model answer, persisted on
// `settings.morningBrief.lastSuggestions` so the UI can queue them in one click.
// ---------------------------------------------------------------------------

function parseSuggestionsJson(raw) {
  const text = String(raw || '').trim()
  if (!text) return []
  let candidate = text
  const fence = /^`{3,}[A-Za-z0-9_-]*[ \t]*\n([\s\S]*?)\n?`{3,}[ \t]*$/.exec(candidate)
  if (fence) candidate = fence[1].trim()
  const attempt = value => {
    try {
      const parsed = JSON.parse(value)
      return Array.isArray(parsed) ? parsed : null
    } catch {
      return null
    }
  }
  let parsed = attempt(candidate)
  if (parsed === null) {
    const start = candidate.indexOf('[')
    const end = candidate.lastIndexOf(']')
    if (start >= 0 && end > start) parsed = attempt(candidate.slice(start, end + 1))
  }
  return parsed || []
}

/**
 * Split a model answer into (markdown body without markers, suggestions).
 * A missing/invalid JSON block yields an empty list and does not affect the
 * body; the marker block is always removed from the markdown.
 */
export function extractBriefSuggestions(text) {
  const source = String(text || '')
  const start = source.indexOf(BRIEF_SUGGESTION_START)
  let content = source
  let raw = ''
  if (start >= 0) {
    const end = source.indexOf(BRIEF_SUGGESTION_END, start + BRIEF_SUGGESTION_START.length)
    raw = end >= 0
      ? source.slice(start + BRIEF_SUGGESTION_START.length, end)
      : source.slice(start + BRIEF_SUGGESTION_START.length)
    content = end >= 0
      ? source.slice(0, start) + source.slice(end + BRIEF_SUGGESTION_END.length)
      : source.slice(0, start)
  }
  content = content.split(BRIEF_SUGGESTION_START).join(' ').split(BRIEF_SUGGESTION_END).join(' ').trim()
  return { content, suggestions: normalizeSuggestions(parseSuggestionsJson(raw)) }
}

/**
 * Deterministic suggestions when the model did not return a usable JSON block:
 * up to two pending tasks (claim order) plus the newest idea.
 */
export function buildFallbackSuggestions({ candidates = [], ideas = [] } = {}) {
  const suggestions = []
  for (const task of (Array.isArray(candidates) ? candidates : []).slice(0, 2)) {
    const suggestion = normalizeSuggestion({
      title: taskTitle(task),
      reason: '已在队列排队',
      prompt: task.prompt || task.title,
      priority: task.priority,
    })
    if (suggestion) suggestions.push(suggestion)
  }
  const idea = Array.isArray(ideas) && ideas.length > 0 ? ideas[0] : null
  if (idea && suggestions.length < MAX_BRIEF_SUGGESTIONS) {
    const suggestion = normalizeSuggestion({
      title: taskTitle(idea),
      reason: '想法待排期',
      prompt: idea.prompt || idea.title,
      priority: idea.priority,
    })
    if (suggestion) suggestions.push(suggestion)
  }
  return suggestions.slice(0, MAX_BRIEF_SUGGESTIONS)
}

// ---------------------------------------------------------------------------
// Prompt + deterministic fallback.
// ---------------------------------------------------------------------------

function promptDigestLines(sessionDigests) {
  if (!Array.isArray(sessionDigests) || sessionDigests.length === 0) return ['- 无']
  return sessionDigests.map(digest => {
    const title = cleanInline(digest.title) || 'DSH 会话'
    const ask = cleanInline(digest.ask) || '（无首条提问记录）'
    const answer = cleanInline(digest.answer) || '（无最后结论记录）'
    return `- 会话「${title}」\n  用户问：${ask}\n  最后结论：${answer}`
  })
}

/**
 * The fixed v0.7 morning-brief request: yesterday's real content, today's
 * queue/ideas/waits and a structured suggestion block the Host persists.
 */
export function buildMorningBriefPrompt(input = {}) {
  const date = isRealDate(input.date) ? input.date : localDateString()
  const yesterday = Array.isArray(input.yesterday)
    ? input.yesterday
    : (input.yesterday && Array.isArray(input.yesterday.tasks) ? input.yesterday.tasks : [])
  const reportText = typeof input.reportText === 'string' ? input.reportText.trim() : ''
  const sessionDigests = Array.isArray(input.sessionDigests) ? input.sessionDigests : []
  const running = Array.isArray(input.running) ? input.running : []
  const waiting = Array.isArray(input.waiting) ? input.waiting : []
  const candidates = Array.isArray(input.candidates) ? input.candidates : []
  const ideas = Array.isArray(input.ideas) ? input.ideas : []
  const proposed = proposedCountOf(input.skills)
  const schedule = input.schedule && typeof input.schedule === 'object' ? input.schedule : {}
  const reportTime = REPORT_TIME_PATTERN.test(String(schedule.reportTime || ''))
    ? schedule.reportTime
    : DEFAULT_SCHEDULE.reportTime
  const retroTime = REPORT_TIME_PATTERN.test(String(schedule.retroTime || ''))
    ? schedule.retroTime
    : DEFAULT_SCHEDULE.retroTime

  const yesterdayLines = yesterday.length > 0
    ? yesterday.slice(0, MAX_YESTERDAY).map(task => {
      const outcome = firstSentence(taskOutcome(task), 140)
      return `- ${taskTitle(task)}${outcome ? `：${outcome}` : ''}`
    })
    : ['- 无']
  const queueLines = candidates.length > 0
    ? candidates.slice(0, 5).map(task => {
      const ask = firstSentence(taskAskText(task), 160)
      return `- ${taskTitle(task)}${ask ? `：${ask}` : ''}`
    })
    : ['- 无']
  const ideaLines = ideas.length > 0
    ? ideas.slice(0, 3).map(task => `- ${taskTitle(task)}：${firstSentence(taskAskText(task), 160) || '暂无描述'}`)
    : ['- 无']
  const waitingLines = waiting.length > 0
    ? waiting.slice(0, MAX_WAITING).map(task => {
      const stamp = taskStamp(task)
      const elapsed = stamp > 0 ? `已等 ${formatElapsed(Date.now() - stamp)}` : ''
      return `- ${statusLabel(task.status)}「${taskTitle(task)}」${elapsed ? `：${elapsed}` : ''}`
    })
    : ['- 无']
  const runningLines = running.length > 0
    ? running.slice(0, 3).map(task => `- ${taskTitle(task)}`)
    : ['- 无']

  return [
    '你是用户的私人助理。请根据下面的真实工作数据，写一份**晨间简报**（简体中文 Markdown），让用户 30 秒内知道：昨天发生了什么、今天建议先做什么、有什么在等他、要提醒什么。',
    '',
    '硬性要求：',
    `1. 只输出 Markdown 正文；第一行必须恰好是「# ${date} ${BRIEF_TITLE}」；不要寒暄、不要解释、不要输出代码块围栏。`,
    '2. 必须严格使用以下四个二级标题，文字与顺序都不能改：',
    BRIEF_SECTIONS[0],
    BRIEF_SECTIONS[1],
    BRIEF_SECTIONS[2],
    BRIEF_SECTIONS[3],
    '3. 「昨天发生了什么」写 2–4 条具体结论，优先使用昨天的工作日志和 DSH 会话摘要；不要写状态计数与空话。',
    '4. 「今天建议先做」写 1–3 条「**做什么** — 为什么是它」，依据昨天的未完成、队列顺序、想法或截止时间。',
    '5. 「等你处理」最多 4 条，没有就写「- 无」。',
    `6. 「提醒」写 1–3 条简短提醒（等待超时、技能候选、今天的定时节点：日报 ${reportTime}、复盘 ${retroTime}）。`,
    '7. 正文总长 400–700 字；不写 token、模型、路径、会话 ID 等技术细节；不要编造数据之外的内容。',
    '8. 正文最后追加结构化建议（不要放进任何代码围栏），格式严格如下：',
    BRIEF_SUGGESTION_START,
    '[{"title":"≤60字","reason":"≤80字","prompt":"≤500字，可直接作为任务描述","priority":"urgent|high|normal|low"}]',
    BRIEF_SUGGESTION_END,
    '9. 建议写 1–3 条，与「今天建议先做」一致；没有就给空数组 []。',
    '',
    `今天是 ${date}。数据如下：`,
    '',
    '昨天的工作日志：',
    reportText || '- 无',
    '',
    '昨天的 DSH 会话摘要（真实会话内容，优先使用）：',
    ...promptDigestLines(sessionDigests),
    '',
    '昨天结束的任务：',
    ...yesterdayLines,
    '',
    '今天的队列（按执行顺序）：',
    ...queueLines,
    '',
    '想法（最近 3 个）：',
    ...ideaLines,
    '',
    '等你处理：',
    ...waitingLines,
    '',
    '进行中：',
    ...runningLines,
    '',
    `待采纳的技能候选：${proposed} 个`,
  ].join('\n')
}

function yesterdayTaskLine(task) {
  const outcome = firstSentence(taskOutcome(task), 140)
  return `- ${taskTitle(task)}${outcome ? `：${outcome}` : ''}`
}

/** Deterministic four-section brief; always readable and never invents data. */
export function buildMorningBriefFallback(input = {}) {
  const date = isRealDate(input.date) ? input.date : localDateString()
  const now = Number.isFinite(input.now) ? input.now : Date.now()
  const yesterday = Array.isArray(input.yesterday) ? input.yesterday : []
  const reportText = typeof input.reportText === 'string' ? input.reportText : ''
  const sessionDigests = Array.isArray(input.sessionDigests) ? input.sessionDigests : []
  const running = Array.isArray(input.running) ? input.running : []
  const waiting = Array.isArray(input.waiting) ? input.waiting : []
  const candidates = Array.isArray(input.candidates) ? input.candidates : []
  const ideas = Array.isArray(input.ideas) ? input.ideas : []
  const proposed = proposedCountOf(input.skills)
  const schedule = input.schedule && typeof input.schedule === 'object' ? input.schedule : {}
  const reportTime = REPORT_TIME_PATTERN.test(String(schedule.reportTime || ''))
    ? schedule.reportTime
    : DEFAULT_SCHEDULE.reportTime
  const retroTime = REPORT_TIME_PATTERN.test(String(schedule.retroTime || ''))
    ? schedule.retroTime
    : DEFAULT_SCHEDULE.retroTime

  const lines = [`# ${date} ${BRIEF_TITLE}`, '', BRIEF_SECTIONS[0], '']
  const happened = []
  for (const text of journalHighlights(reportText, 2)) happened.push(`- ${text}`)
  for (const text of digestHighlights(sessionDigests, 2)) happened.push(`- ${text}`)
  for (const task of yesterday.slice(0, 3)) happened.push(yesterdayTaskLine(task))
  if (happened.length === 0) lines.push('昨天没有记录到工作活动。')
  else lines.push(...happened.slice(0, 6))

  lines.push('', BRIEF_SECTIONS[1], '')
  const suggestions = buildFallbackSuggestions({ candidates, ideas })
  if (suggestions.length === 0) {
    lines.push('今天没有排期，先记下一件想做的事。')
  } else {
    for (const suggestion of suggestions) {
      lines.push(`- **${suggestion.title}** — ${suggestion.reason || '建议今天处理'}`)
    }
  }

  lines.push('', BRIEF_SECTIONS[2], '')
  if (waiting.length === 0) {
    lines.push('- 无')
  } else {
    for (const task of waiting.slice(0, MAX_WAITING)) {
      const stamp = taskStamp(task)
      const elapsed = stamp > 0 ? `已等 ${formatElapsed(now - stamp)}` : '等待处理'
      lines.push(`- ${statusLabel(task.status)}「${taskTitle(task)}」：${elapsed}`)
    }
  }

  lines.push('', BRIEF_SECTIONS[3], '')
  const risks = []
  for (const task of waiting) {
    if (risks.length >= MAX_RISK) break
    if (task.status !== 'blocked') continue
    const stamp = taskStamp(task)
    if (stamp > 0 && now - stamp > RISK_STALE_MS) {
      risks.push(`- 「${taskTitle(task)}」已等你 ${formatElapsed(now - stamp)}，建议先处理。`)
    }
  }
  for (const task of running) {
    if (risks.length >= MAX_RISK) break
    const started = Number.isFinite(task.startedAt) ? task.startedAt : 0
    if (started > 0 && now - started > RISK_STALE_MS) {
      risks.push(`- 「${taskTitle(task)}」已运行 ${formatElapsed(now - started)}。`)
    }
  }
  if (proposed > 0 && risks.length < MAX_RISK) risks.push(`- 有 ${proposed} 个技能候选待采纳。`)
  if (risks.length < MAX_RISK) {
    risks.push(`- 今天的定时节点：日报 ${reportTime}、复盘 ${retroTime}。`)
  }
  lines.push(...(risks.length > 0 ? risks.slice(0, MAX_RISK) : ['- 暂无特别提醒。']))

  return `${lines.join('\n').replace(/\n{3,}/g, '\n\n').trim()}\n`
}

// ---------------------------------------------------------------------------
// Output normalisation.
// ---------------------------------------------------------------------------

const BRIEF_HEADING = /^# \d{4}-\d{2}-\d{2} 晨间简报/

/**
 * Extract exactly the brief body from a model answer. A missing title is
 * prepended; surrounding narration before the heading is dropped. The result
 * is trimmed and ends with exactly one newline.
 */
export function extractBriefBody(text, date) {
  const day = isRealDate(date) ? date : localDateString()
  const normalized = String(text || '').replace(/\r\n?/g, '\n')
  const lines = normalized.split('\n')
  let start = -1
  for (let index = 0; index < lines.length; index += 1) {
    if (BRIEF_HEADING.test(lines[index].trim())) {
      start = index
      break
    }
  }
  let body
  if (start >= 0) {
    body = [lines[start].trim(), ...lines.slice(start + 1)].join('\n')
  } else {
    body = `# ${day} ${BRIEF_TITLE}\n\n${normalized}`
  }
  body = body.trimEnd()
  if (!body) body = `# ${day} ${BRIEF_TITLE}`
  return `${body}\n`
}

function technicalLine(line) {
  return /(token|tokens|模型|路径|会话\s*(id|ID)|cwd|provider)/i.test(line)
}

/**
 * Model output is normalised before writing: a missing/reshuffled section
 * structure falls back to the deterministic brief; otherwise headings keep
 * their order, technical lines are dropped, bullets are shortened and each
 * section is capped. The brief always stays a summary.
 */
/**
 * Model output is normalised before writing: a missing/reshuffled section
 * structure falls back to the deterministic brief; otherwise headings keep
 * their order, technical metadata lines are dropped, bullets are shortened and
 * each section is capped. Concrete content (numbers/files/links) is preserved.
 */
export function normalizeMorningBriefText(text, date, data = {}) {
  const day = isRealDate(date) ? date : localDateString()
  const body = extractBriefBody(text, date)
  const positions = BRIEF_SECTIONS.map(section => body.indexOf(section))
  const structured = positions.every(index => index >= 0) &&
    positions.every((value, index) => index === 0 || value > positions[index - 1])
  if (!structured) {
    return { content: buildMorningBriefFallback({ date: day, ...(data || {}) }), fallback: true }
  }
  const sections = []
  let current = null
  for (const raw of body.split('\n')) {
    const line = raw.replace(/\s+$/, '')
    const heading = BRIEF_SECTIONS.find(section => line.trim() === section)
    if (heading) {
      current = { heading, lines: [] }
      sections.push(current)
      continue
    }
    if (!current) continue
    if (line.trim() === '') {
      if (current.lines.length > 0 && current.lines[current.lines.length - 1] !== '') current.lines.push('')
      continue
    }
    const value = line.trim()
    if (technicalLine(value)) continue
    if (/^[-*+]\s+/.test(value)) {
      const bulletBody = compact(value.replace(/^[-*+]\s+/, ''), MAX_BULLET_CHARS)
      if (bulletBody === '') continue
      current.lines.push(`- ${bulletBody}`)
    } else if (sections.length === 1) {
      // Only the first section may carry a short prose paragraph.
      current.lines.push(compact(value, 300))
    }
  }
  const limits = [4, 3, MAX_WAITING, MAX_RISK]
  const out = [`# ${day} ${BRIEF_TITLE}`, '']
  sections.forEach((section, index) => {
    const limit = limits[index] || MAX_WAITING
    let bullets = 0
    const kept = []
    for (const line of section.lines) {
      if (line.startsWith('- ')) {
        bullets += 1
        if (bullets > limit) continue
      }
      kept.push(line)
    }
    while (kept.length && kept[kept.length - 1] === '') kept.pop()
    if (kept.length === 0) kept.push('- 无')
    out.push(section.heading, '', ...kept, '')
  })
  let content = out.join('\n').replace(/\n{3,}/g, '\n\n').trim()
  if (content.length > MAX_BRIEF_CHARS) content = `${content.slice(0, MAX_BRIEF_CHARS).trimEnd()}…`
  return { content: `${content}\n`, fallback: false }
}

// ---------------------------------------------------------------------------
// Files.
// ---------------------------------------------------------------------------

/** Newest-first brief files under `dir`, at most `limit` entries. */
export function listBriefFiles(dir, limit = BRIEF_LIST_LIMIT) {
  if (typeof dir !== 'string' || dir === '') return []
  let names = []
  try {
    names = readdirSync(dir)
  } catch {
    return []
  }
  const files = []
  for (const name of names) {
    if (!FILE_PATTERN.test(name)) continue
    const path = join(dir, name)
    try {
      const info = statSync(path)
      if (!info.isFile()) continue
      files.push({ date: name.slice(0, -3), path, bytes: info.size, updatedAt: info.mtimeMs })
    } catch {
      // A file removed between readdir and stat is simply skipped.
    }
  }
  files.sort((left, right) => (left.date < right.date ? 1 : left.date > right.date ? -1 : 0))
  const max = Number.isFinite(limit) ? Math.max(1, Math.min(BRIEF_LIST_LIMIT, Math.floor(limit))) : BRIEF_LIST_LIMIT
  return files.slice(0, max)
}

/** Read one brief; missing file -> undefined, invalid date -> 400. */
export function readBriefFile(dir, date) {
  const text = String(date || '')
  if (!isRealDate(text)) throw new HttpError(400, '日期格式应为 YYYY-MM-DD')
  if (typeof dir !== 'string' || dir === '') return undefined
  const path = join(dir, `${text}.md`)
  if (!existsSync(path)) return undefined
  return readFileSync(path, 'utf8')
}

// ---------------------------------------------------------------------------
// Engine.
// ---------------------------------------------------------------------------

/**
 * Create the morning-brief engine (mirrors `createReports`).
 *
 * The engine owns one 30s timer, one background Session per generation, the
 * atomic file write and the restart recovery pass. The settings handler calls
 * `kick()` after a settings update so a changed time takes effect immediately.
 */
export function createBriefs({ ctx, store, bridge, notify, options = {} }) {
  const tickMs = Number.isFinite(options.tickMs) ? options.tickMs : BRIEF_TICK_MS
  const pollMs = Number.isFinite(options.pollMs) ? options.pollMs : BRIEF_POLL_MS
  const maxWaitMs = Number.isFinite(options.maxWaitMs) ? options.maxWaitMs : BRIEF_MAX_WAIT_MS
  const push = typeof notify === 'function' ? notify : () => {}
  let timer = null
  let kickHandle = null
  let disposed = false

  function log(...args) {
    try {
      console.log('[personal-secretary]', ...args)
    } catch {
      // logging must never break brief generation
    }
  }

  function settings() {
    return (store.settings && store.settings.morningBrief) || {}
  }

  function briefDir() {
    const value = settings()
    return typeof value.dir === 'string' && value.dir !== '' ? value.dir : join(store.dir, 'briefs')
  }

  function today() {
    return localDateString(Date.now())
  }

  function list() {
    return listBriefFiles(briefDir())
  }

  function read(date) {
    return readBriefFile(briefDir(), date)
  }

  function pathOf(date) {
    return join(briefDir(), `${String(date || '')}.md`)
  }

  function meta() {
    return { briefs: list(), settings: { ...settings() } }
  }

  function schedule() {
    const daily = store.settings && store.settings.dailyReport ? store.settings.dailyReport : {}
    const evolution = store.settings && store.settings.evolution ? store.settings.evolution : {}
    return {
      reportTime: REPORT_TIME_PATTERN.test(String(daily.time || '')) ? daily.time : DEFAULT_SCHEDULE.reportTime,
      retroTime: REPORT_TIME_PATTERN.test(String(evolution.time || '')) ? evolution.time : DEFAULT_SCHEDULE.retroTime,
    }
  }

  function writeBriefFile(date, content) {
    const dir = briefDir()
    mkdirSync(dir, { recursive: true })
    const target = join(dir, `${date}.md`)
    const tmp = join(dir, `.${date}.md.${process.pid}.${Date.now()}.tmp`)
    writeFileSync(tmp, content, 'utf8')
    renameSync(tmp, target)
    return target
  }

  async function collect(date) {
    const dir = briefDir()
    mkdirSync(dir, { recursive: true })
    const data = collectMorningBriefData(store, Date.now(), date)
    // v0.7: real content — yesterday's work journal + yesterday's session
    // questions/answers, plus the current queue/ideas/waits.
    const yesterday = previousDateString(date)
    const reportText = readJournalText(store, yesterday)
    let sessionDigests = []
    try {
      sessionDigests = await collectSessionDigests({ store, bridge, date: yesterday, limit: MAX_DIGESTS })
    } catch {
      sessionDigests = []
    }
    const briefData = { ...data, reportText, sessionDigests }
    const prompt = buildMorningBriefPrompt({ date, ...briefData, schedule: schedule() })
    const sessionId = await bridge.createSession({ cwd: dir })
    // The brief's Session is ours: it must not show up as a workspace import.
    store.ownSession(sessionId)
    await bridge.selectModel(sessionId, {
      provider: store.settings.provider,
      model: store.settings.model,
      reasoningEffort: store.settings.reasoningEffort,
    })
    const startedAt = Date.now()
    await bridge.prompt(sessionId, prompt)
    const deadline = startedAt + maxWaitMs
    for (;;) {
      if (disposed) throw new Error('晨间简报生成已取消：插件已停止')
      const last = await bridge.lastTurnEnd(sessionId)
      if (last && last.reason) {
        const time = Number.isFinite(last.time) ? last.time : startedAt
        if (time >= startedAt - 1000) break
      }
      if (Date.now() >= deadline) throw new Error('晨间简报生成超时（10 分钟）')
      await sleep(pollMs)
    }
    const summary = await bridge.summarize(sessionId)
    const text = String(summary.finalAnswer || '').trim()
    if (!text) {
      log('brief model returned no content, using the local fallback')
      return {
        content: buildMorningBriefFallback({ date, ...briefData, now: Date.now(), schedule: schedule() }),
        suggestions: buildFallbackSuggestions(briefData),
      }
    }
    const extracted = extractBriefSuggestions(text)
    const suggestions = extracted.suggestions.length > 0
      ? extracted.suggestions
      : buildFallbackSuggestions(briefData)
    const normalized = normalizeMorningBriefText(extracted.content, date, briefData)
    if (normalized.fallback) log('brief model output missed the fixed structure, using the local fallback')
    return { content: normalized.content, suggestions }
  }

  async function runGeneration(date) {
    try {
      const generated = await collect(date)
      const path = writeBriefFile(date, generated.content)
      store.updateMorningBrief({
        lastDate: date,
        lastStatus: 'ok',
        lastError: null,
        lastGeneratedAt: Date.now(),
        generatingDate: null,
        lastSuggestions: generated.suggestions,
      })
      push('morningBrief', {
        date,
        content: generated.content,
        path,
        suggestions: generated.suggestions,
      })
    } catch (error) {
      log('brief generation failed:', errorMessage(error))
      store.updateMorningBrief({
        lastStatus: 'failed',
        lastError: trimError(errorMessage(error), 500),
        generatingDate: null,
      })
    }
  }

  function generate(date) {
    const target = date === undefined || date === null || date === ''
      ? today()
      : String(date).trim()
    if (!isRealDate(target)) throw new HttpError(400, '日期格式应为 YYYY-MM-DD')
    if (settings().generatingDate) throw new HttpError(409, '晨间简报正在生成中')
    store.updateMorningBrief({ generatingDate: target, lastStatus: 'running', lastError: null })
    void runGeneration(target)
    return { ok: true, date: target }
  }

  async function checkDue(now = Date.now()) {
    try {
      if (disposed) return
      if (!isBriefDue(settings(), now)) return
      generate(localDateString(now))
    } catch (error) {
      log('brief due check failed:', errorMessage(error))
    }
  }

  function recoverStale() {
    const current = settings()
    if (current.lastStatus === 'running' || current.generatingDate) {
      store.updateMorningBrief({
        lastStatus: 'failed',
        lastError: '上次晨间简报生成未完成（进程已重启）',
        generatingDate: null,
      })
    }
  }

  function start() {
    if (timer || disposed) return
    recoverStale()
    timer = setInterval(() => { void checkDue() }, tickMs)
    if (typeof timer === 'object' && timer && typeof timer.unref === 'function') timer.unref()
    void checkDue()
  }

  function stop() {
    disposed = true
    if (timer) clearInterval(timer)
    timer = null
    if (kickHandle) clearTimeout(kickHandle)
    kickHandle = null
  }

  /** Immediate re-check after the schedule settings changed. */
  function kick() {
    if (disposed) return
    if (kickHandle) return
    kickHandle = setTimeout(() => {
      kickHandle = null
      void checkDue()
    }, 50)
    if (kickHandle && typeof kickHandle.unref === 'function') kickHandle.unref()
  }

  recoverStale()

  return {
    start,
    stop,
    kick,
    list,
    read,
    meta,
    today,
    generate,
    checkDue,
    recoverStale,
    isGenerating: () => Boolean(settings().generatingDate),
    briefDir,
    pathOf,
  }
}

export { STATUS_LABELS, DEFAULT_SCHEDULE, normalizeSuggestion, normalizeSuggestions as normalizeBriefSuggestions }
